#!/bin/sh
# Customise the project generated by `tauri android init` (run from the repo root; GNU and BSD sed).
set -e
GEN=src-tauri/gen/android/app/src/main
# Keyboard and system-bar insets (edge-to-edge would let the keyboard cover inputs).
cp src-tauri/android/MainActivity.kt "$GEN/java/com/koi/kellyfin/MainActivity.kt"
# Servers are often plain http on the LAN or VPN. Tauri's template sets usesCleartextTraffic through a Gradle
# placeholder that is "false" outside debug builds, so the manifest attribute alone is not enough.
APP_GRADLE=src-tauri/gen/android/app/build.gradle.kts
sed -i.bak 's|manifestPlaceholders\["usesCleartextTraffic"\] = "false"|manifestPlaceholders["usesCleartextTraffic"] = "true"|' "$APP_GRADLE" && rm "$APP_GRADLE.bak"
grep -q usesCleartextTraffic "$GEN/AndroidManifest.xml" ||
  { sed -i.bak 's|<application|<application android:usesCleartextTraffic="true"|' "$GEN/AndroidManifest.xml" && rm "$GEN/AndroidManifest.xml.bak"; }
! grep -q 'usesCleartextTraffic"] = "false"' "$APP_GRADLE" || { echo "cleartext still disabled in $APP_GRADLE"; exit 1; }
# Build-logic plugins also live on Maven Central; the plugin portal alone misses them on a fresh cache.
grep -q pluginManagement src-tauri/gen/android/settings.gradle ||
  { printf 'pluginManagement {\n    repositories {\n        gradlePluginPortal()\n        google()\n        mavenCentral()\n    }\n}\n\n'; cat src-tauri/gen/android/settings.gradle; } > src-tauri/gen/android/settings.tmp &&
  mv src-tauri/gen/android/settings.tmp src-tauri/gen/android/settings.gradle
grep -n "usesCleartextTraffic" "$GEN/AndroidManifest.xml" "$APP_GRADLE"
